    "privacy.whoTitle": "Vem som driver PluggEra och vem som hanterar din data",
    "privacy.whoBody": "PluggEra drivs av två privatpersoner; inget bolag är bildat än. Tjänsten körs hos Fly.io i Amsterdam (EU). När du använder en AI-funktion skickas texten eller fotot du skickar (och, för handledaren, ditt förnamn och din studienivå) till Anthropic, som levererar AI:n och kan behandla det utanför EU. Loggar du in med Google är Google inblandat i själva inloggningen. PluggEra använder inga tredjeparts analys-, annons- eller spårningstjänster — den anonyma signalen som beskrivs ovan räknas på PluggEras egen server, ingen annans — och laddar sina typsnitt från sin egen server.",
