    "privacy.keepBody": "Ditt konto och dess synkade data sparas tills du raderar kontot i Inställningar. En inloggning gäller i 30 dagar. Värdens serverloggar innehåller tekniska uppgifter som ett internt konto-ID, förfrågningsstorlekar och fel, aldrig texten i dina meddelanden, och sparas under begränsad tid.",
