    "about.pageTitle": "Om PluggEra",
    "about.heroLead": "En pluggapp byggd kring en enda idé: att plugga fungerar bättre när det är enkelt, ärligt om vad det kan och inte kan göra, och aldrig försöker sälja dig något.",
    "about.missionTitle": "Vad PluggEra är",
    "about.missionBody": "Ett färdigt övningsbibliotek per årskurs och ämne, verktyg för att göra dina egna anteckningar eller ett foto till ett frågeset, repetition som tar tillbaka frågor precis innan du skulle glömma dem, och — när du är inloggad — en AI-handledare och fotolösning. Att öva fungerar utan konto; AI-funktionerna är tillägg, inte grunden.",
    "about.levelsTitle": "Vad PluggEra täcker",
    "about.levelsBody": "Färdiga övningar genom hela den svenska läroplanen, plus ett eget spår för högskoleprovet.",
    "about.backgroundTitle": "Bakgrund",
    "about.backgroundBody": "PluggEra byggs och underhålls som ett fristående, småskaligt projekt — inget företag, inte finansierat av annonser eller genom att sälja data. Det finns för att pluggverktyg som faktiskt är trevliga att använda är mer sällsynta än de borde vara.",
    "about.contactTitle": "Hör av dig",
    "about.contactBody": "Hittat en bugg, har en idé, eller bara vill säga hej? Feedback går rakt till dem som bygger det här.",
    "about.contactLink": "Skicka feedback",
    "contact.pageTitle": "Kontakta oss",
    "contact.lead": "Har du frågor, idéer eller hittat en bugg? Skriv till oss. Det går direkt till dem som bygger PluggEra.",
